"""Safe comms-test policy for agent_0 in crossed_waypoints."""

import json
import time
from skills import comms, frames, safety


def parse_target(payload):
    if isinstance(payload, str):
        try:
            payload = json.loads(payload)
        except Exception:
            return None
    if isinstance(payload, (list, tuple)) and len(payload) >= 2:
        try:
            return [float(payload[0]), float(payload[1])]
        except (ValueError, TypeError):
            pass
    if isinstance(payload, dict):
        for key in ["target", "center", "waypoint", "point", "pos", "position"]:
            val = payload.get(key)
            if isinstance(val, (list, tuple)) and len(val) >= 2:
                try:
                    return [float(val[0]), float(val[1])]
                except (ValueError, TypeError):
                    pass
            elif isinstance(val, dict) and "x" in val and "y" in val:
                try:
                    return [float(val["x"]), float(val["y"])]
                except (ValueError, TypeError):
                    pass
        if "x" in payload and "y" in payload:
            try:
                return [float(payload["x"]), float(payload["y"])]
            except (ValueError, TypeError):
                pass
    return None


def parse_radius(payload, default=0.2):
    if isinstance(payload, str):
        try:
            payload = json.loads(payload)
        except Exception:
            return default
    if isinstance(payload, dict):
        for key in ["radius", "r", "rad"]:
            val = payload.get(key)
            if val is not None:
                try:
                    return float(val)
                except (ValueError, TypeError):
                    pass
    return default


def on_start(ctx):
    ctx.state["observation"] = None
    ctx.state["inbox_count"] = 0
    ctx.state["my_target"] = None
    ctx.state["my_target_radius"] = 0.2
    ctx.state["my_target_t"] = None
    ctx.log("policy started: holding position and establishing comms")


def on_observation(ctx, observation):
    ctx.state["observation"] = observation


def on_inbox(ctx, message):
    payload = comms.payload_of(message)
    t_now = time.time()
    ctx.state["inbox_count"] = ctx.state.get("inbox_count", 0) + 1
    ctx.state["last_inbox_t"] = t_now
    ctx.state["last_payload"] = payload

    target = parse_target(payload)
    radius = parse_radius(payload)
    if target is not None:
        ctx.state["my_target"] = target
        ctx.state["my_target_radius"] = radius
        ctx.state["my_target_t"] = t_now


def on_tick(ctx):
    obs = ctx.state.get("observation")
    if not obs:
        ctx.publish_action({"vx": 0.0, "vy": 0.0, "omega": 0.0})
        ctx.status({"mode": "waiting_for_observation"})
        return

    # Broadcast teammate's target if known
    scenario = obs.get("scenario", {})
    peer_wp = scenario.get("peer_waypoint")
    if peer_wp is not None:
        msg = {
            "type": "peer_waypoint",
            "target": peer_wp.get("center"),
            "radius": peer_wp.get("radius", 0.2),
            "expires_in_s": peer_wp.get("expires_in_s"),
            "for": peer_wp.get("agent_id", "agent_1"),
        }
        ctx.send_message(msg, recipient="agent_1")

    # Safe hold (zero velocity + safety guards)
    action = safety.safe(obs, {"vx": 0.0, "vy": 0.0, "omega": 0.0})
    ctx.publish_action(action)

    # Telemetry
    pose = frames.pose_of(obs)
    my_prog = scenario.get("my_progress", {})
    target = ctx.state.get("my_target")
    target_age = (
        round(time.time() - ctx.state["my_target_t"], 2)
        if ctx.state.get("my_target_t")
        else None
    )

    ctx.status({
        "mode": "holding_test_comms",
        "pos": [round(pose[0], 3), round(pose[1], 3)],
        "heading": round(pose[2], 3),
        "my_progress": my_prog,
        "peer_wp_sent": peer_wp.get("center") if peer_wp else None,
        "peer_wp_expires": round(peer_wp.get("expires_in_s", 0), 1) if peer_wp else None,
        "received_target": [round(x, 3) for x in target] if target else None,
        "target_age_s": target_age,
        "inbox_count": ctx.state.get("inbox_count", 0),
    })

"""Autonomous coordination and navigation policy for agent_0 in crossed_waypoints."""

import json
import math
import time
from skills import base_policy, comms, frames, nav, safety

_STOP = {"vx": 0.0, "vy": 0.0, "omega": 0.0}
_STOPPED_MPS = 0.01


def find_target_in_obj(obj, depth=0):
    """Recursively extract [x, y] coordinates from any message payload shape."""
    if depth > 4 or obj is None:
        return None
    if isinstance(obj, str):
        try:
            obj = json.loads(obj)
        except Exception:
            return None
    if (
        isinstance(obj, (list, tuple))
        and len(obj) >= 2
        and all(isinstance(x, (int, float)) for x in obj[:2])
    ):
        return [float(obj[0]), float(obj[1])]
    if isinstance(obj, dict):
        if (
            "x" in obj
            and "y" in obj
            and isinstance(obj["x"], (int, float))
            and isinstance(obj["y"], (int, float))
        ):
            return [float(obj["x"]), float(obj["y"])]
        for k in [
            "target",
            "center",
            "waypoint",
            "peer_waypoint",
            "point",
            "pos",
            "position",
            "goal",
            "wp",
            "loc",
            "location",
            "coord",
            "coordinates",
        ]:
            if k in obj:
                res = find_target_in_obj(obj[k], depth + 1)
                if res is not None:
                    return res
        for v in obj.values():
            if isinstance(v, (dict, list, str)):
                res = find_target_in_obj(v, depth + 1)
                if res is not None:
                    return res
    return None


def find_radius_in_obj(obj, depth=0, default=0.2):
    """Recursively extract radius if present, defaulting to 0.2."""
    if depth > 4 or obj is None:
        return default
    if isinstance(obj, str):
        try:
            obj = json.loads(obj)
        except Exception:
            return default
    if isinstance(obj, dict):
        for k in ["radius", "r", "rad"]:
            if k in obj:
                try:
                    return float(obj[k])
                except (ValueError, TypeError):
                    pass
        for v in obj.values():
            if isinstance(v, (dict, str)):
                res = find_radius_in_obj(v, depth + 1, default=None)
                if res is not None:
                    return res
    return default


def _nearest_hazard(obs):
    try:
        return nav.nearest_hazard(obs)
    except ValueError:
        return None


def _blocked_by(obs, commanded, published, hazard_mode=None, hazard=None):
    if math.hypot(published.get("vx", 0.0), published.get("vy", 0.0)) >= _STOPPED_MPS:
        return None
    light = ((obs or {}).get("global_signals") or {}).get("my_light")
    if (
        isinstance(light, dict)
        and str(light.get("state", "green")).lower() == "red"
    ):
        return "red_light"
    if hazard_mode == "waiting":
        return "hazard_waiting"
    if math.hypot(commanded.get("vx", 0.0), commanded.get("vy", 0.0)) >= _STOPPED_MPS:
        return "wall_reflex"
    if hazard is not None and hazard.get("inside", False):
        return f"{hazard['kind']}_standoff"
    if hazard is not None:
        return "yielding"
    return "no_command"


def on_start(ctx):
    ctx.state["observation"] = None
    ctx.state["inbox_count"] = 0
    ctx.state["current_target"] = None
    ctx.state["current_radius"] = 0.2
    ctx.state["target_updated_t"] = None
    ctx.state["completed_target"] = None
    ctx.state["completed_t"] = None
    ctx.state["last_reached_count"] = 0
    ctx.state["arrived_at_target"] = False
    ctx.state["arrived_t"] = None
    ctx.state["nav"] = {}
    ctx.state["hazard"] = {}
    ctx.state["wall"] = {}
    ctx.log("policy started: autonomous waypoint coordination and navigation")


def on_observation(ctx, observation):
    ctx.state["observation"] = observation


def on_inbox(ctx, message):
    payload = comms.payload_of(message)
    t_now = time.time()
    ctx.state["inbox_count"] = ctx.state.get("inbox_count", 0) + 1
    ctx.state["last_inbox_t"] = t_now

    target = find_target_in_obj(payload)
    radius = find_radius_in_obj(payload, default=0.2)

    if target is not None:
        # Check if this target is the one we just completed
        completed = ctx.state.get("completed_target")
        completed_t = ctx.state.get("completed_t")
        if (
            completed is not None
            and completed_t is not None
            and (t_now - completed_t < 4.0)
        ):
            dist_to_completed = math.hypot(
                target[0] - completed[0], target[1] - completed[1]
            )
            if dist_to_completed < 0.15:
                return

        cur = ctx.state.get("current_target")
        if cur is None or math.hypot(target[0] - cur[0], target[1] - cur[1]) > 0.05:
            ctx.state["current_target"] = target
            ctx.state["current_radius"] = radius
            ctx.state["target_updated_t"] = t_now
            ctx.state["arrived_at_target"] = False
            ctx.state["arrived_t"] = None
            ctx.state["nav"] = {}  # reset nav cache for new goal
            ctx.log(f"New target received from peer: {target} (radius={radius})")
        else:
            ctx.state["target_updated_t"] = t_now


def on_tick(ctx):
    obs = ctx.state.get("observation")
    if not obs:
        ctx.publish_action(dict(_STOP))
        ctx.status({"mode": "waiting_for_observation"})
        return

    t_now = time.time()
    scenario = obs.get("scenario", {})
    my_prog = scenario.get("my_progress", {})
    reached = my_prog.get("reached", 0)
    required = my_prog.get("required", 8)

    # 1. Check if our target was completed
    last_reached = ctx.state.get("last_reached_count", 0)
    if reached > last_reached:
        ctx.log(f"Target count reached: {reached}/{required}!")
        ctx.state["last_reached_count"] = reached
        ctx.state["completed_target"] = ctx.state.get("current_target")
        ctx.state["completed_t"] = t_now
        ctx.state["current_target"] = None
        ctx.state["arrived_at_target"] = False
        ctx.state["arrived_t"] = None
        ctx.state["nav"] = {}

    # 2. Broadcast peer's target if available
    peer_wp = scenario.get("peer_waypoint")
    if peer_wp is not None and peer_wp.get("center") is not None:
        msg = {
            "type": "peer_waypoint",
            "target": peer_wp.get("center"),
            "center": peer_wp.get("center"),
            "radius": peer_wp.get("radius", 0.2),
            "expires_in_s": peer_wp.get("expires_in_s"),
            "for": "agent_1",
        }
        ctx.send_message(msg, recipient="agent_1")
    elif peer_wp is None and reached >= required:
        ctx.send_message(
            {"type": "peer_done", "agent_0_done": True}, recipient="agent_1"
        )

    # 3. Check if all our targets are finished
    if reached >= required:
        action = safety.safe(obs, dict(_STOP))
        ctx.publish_action(action)
        ctx.status({
            "mode": "all_targets_complete",
            "progress": f"{reached}/{required}",
            "inbox_count": ctx.state.get("inbox_count", 0),
        })
        return

    # 4. Target Navigation / Dwell
    target = ctx.state.get("current_target")
    if target is None:
        # No target known yet: hold position safely
        action = safety.safe(obs, dict(_STOP))
        ctx.publish_action(action)
        ctx.status({
            "mode": "waiting_for_peer_target",
            "progress": f"{reached}/{required}",
            "inbox_count": ctx.state.get("inbox_count", 0),
            "peer_wp_sent": peer_wp.get("center") if peer_wp else None,
        })
        return

    pose = frames.pose_of(obs)
    rx, ry, _ = pose
    dist = math.hypot(target[0] - rx, target[1] - ry)
    radius = ctx.state.get("current_radius", 0.2)

    # Hysteresis for arrival & dwell
    in_arrival_zone = ctx.state.get("arrived_at_target", False)
    if in_arrival_zone:
        if dist > 0.12:
            in_arrival_zone = False
            ctx.state["arrived_at_target"] = False
            ctx.state["arrived_t"] = None
    else:
        if dist <= 0.06:
            in_arrival_zone = True
            ctx.state["arrived_at_target"] = True
            ctx.state["arrived_t"] = t_now
            ctx.log(f"Arrived at target {target} (dist={round(dist, 3)}m), dwelling")

    hazard_mode = None
    if in_arrival_zone:
        command = dict(_STOP)
    else:
        action = nav.goto_point(
            obs,
            target,
            ctx.state.setdefault("nav", {}),
            max_speed=0.20,
            arrival_radius=0.06,
            avoid_moving=True,
            route_around_moving=True,
        )
        arrived = action is None
        if arrived:
            ctx.state["arrived_at_target"] = True
            ctx.state["arrived_t"] = t_now
            command = dict(_STOP)
        else:
            command = action
            try:
                command, hazard_mode = nav.hazard_gate(
                    obs, command, ctx.state.setdefault("hazard", {})
                )
            except Exception:
                hazard_mode = None

    # Collision guards and wall berth
    hazard = _nearest_hazard(obs)
    deflecting = bool(hazard is not None and hazard.get("inside", False))
    hold_the_berth = deflecting

    try:
        berth = safety.wall_berth(
            obs,
            command,
            ctx.state.setdefault("wall", {}),
            clearance=safety.WALL_CLEARANCE,
            floor=safety.WALL_FLOOR_CLEARANCE,
            patience_s=safety.WALL_PATIENCE_S,
            progress_m=safety.WALL_PROGRESS_M,
            deflecting=hold_the_berth,
        )
        published = safety.safe(obs, command, min_clearance=berth)
    except Exception:
        published = safety.safe(obs, command)

    ctx.publish_action(published)

    dwell_time = (
        round(t_now - ctx.state["arrived_t"], 1)
        if ctx.state.get("arrived_t")
        else 0.0
    )
    target_age = (
        round(t_now - ctx.state["target_updated_t"], 1)
        if ctx.state.get("target_updated_t")
        else None
    )

    status = {
        "mode": "dwelling" if in_arrival_zone else "driving",
        "target": [round(x, 3) for x in target],
        "dist_m": round(dist, 3),
        "progress": f"{reached}/{required}",
        "dwell_time_s": dwell_time,
        "target_age_s": target_age,
        "inbox_count": ctx.state.get("inbox_count", 0),
        "peer_wp_sent": peer_wp.get("center") if peer_wp else None,
    }
    if hazard_mode is not None:
        status["hazard"] = hazard_mode
    if deflecting:
        status["deflecting"] = hazard["kind"]
    if not in_arrival_zone:
        blocked = _blocked_by(obs, command, published, hazard_mode, hazard)
        if blocked:
            status["blocked_by"] = blocked

    ctx.status(status)
